#include <cstdio>
#include <cstring>

int main() {
    const int MAX_V = 10000;
    bool prime[MAX_V + 1];
    memset(prime, true, sizeof(prime)); // Initialize all entries as true

    // Sieve of Eratosthenes for prime generation
    for(int i = 2; i * i <= MAX_V; i++) {
        if(prime[i]) {
            for(int k = i * i; k <= MAX_V; k += i) { // Start from i*i
                prime[k] = false; // Mark multiples as non-prime
            }
        }
    }

    int an1, an2, suu;
    while(true) {
        scanf("%d", &suu);
        if(suu == 0) break;

        an1 = -1; // Initialize to -1 to avoid garbage values
        for(int k = 2; k <= suu; k++) {
            if(prime[k - 2] && prime[k]) { // Check if both are prime
                an1 = k - 2;
                an2 = k;
            }
        }
        if (an1 != -1) printf("%d %d\n", an1, an2);
    }
    return 0;
}

